module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [2:0] SP;

reg [3:0] [3:0] stack_mem;
integer i;
always @(posedge Clk) begin
    if(EN == 1'b1) begin
        if(Rst == 1'b1) begin
            SP <= 3'd4;
            for(i = 0; i < 4; i = i + 1) begin
                stack_mem[i] <= 4'd0;
            end
        end else begin
            if(FULL == 1'b0 && RW == 1'b0) begin
                SP <= SP - 1;
                stack_mem[SP] <= dataIn;
            end else if(EMPTY == 1'b0 && RW == 1'b1) begin
                dataOut <= stack_mem[SP];
                stack_mem[SP] <= 4'd0;
                SP <= SP + 1;
            end
        end
    end
end
assign EMPTY = (SP == 3'd4);
assign FULL = (SP == 3'd0);
endmodule
